import { fileURLToPath } from "node:url";
import { Crypto, Effect, FileSystem, Option, Path, Schema } from "effect";
import { CliError } from "effect/cli";
import { HttpClient } from "effect/http";

const PackageJson = Schema.Struct({ name: Schema.String, version: Schema.String });

/** Matches the ` * <package>@<version>:<sha256>` line in a generated file's header. */
const stampPattern = /^ \* (\S+@[^\s@:]+:[0-9a-f]{64})$/m;

/** `<package>@<version>:<sha256 of the schema contents>` for the generator at `specifier`. */
export const generatorStamp = Effect.fn("generatorStamp")(function* (
  specifier: string,
  source: URL | string,
  camelCase = false,
) {
  const generator = yield* generatorPackage(specifier);
  const contents = typeof source === "string" ? source : yield* readSource(source);
  const hash = yield* sha256(camelCase ? `${contents}\0camel-case` : contents);
  return { name: generator.name, stamp: `${generator.name}@${generator.version}:${hash}` };
});

export function fileHeader(
  generator: { readonly name: string; readonly stamp: string },
  camelCase = false,
): string {
  const casingLine = camelCase ? " * Field casing: camelCase\n" : "";

  return `/**
 * This file was auto-generated by ${generator.name}.
 * Do not make direct changes to the file.
 *
 * ${generator.stamp}
${casingLine} */
\n`;
}

export function hasCamelCaseHeader(text: string): boolean {
  return (
    text.startsWith("/**\n * This file was auto-generated by @shipworthy/openapi-typescript.\n") &&
    /^ \* Field casing: camelCase$/m.test(text.slice(0, 400))
  );
}

export function readStamp(text: string): string | undefined {
  return stampPattern.exec(text)?.[1];
}

const generatorPackage = Effect.fn("generatorPackage")(function* (specifier: string) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const name = specifier.split("/", specifier.startsWith("@") ? 2 : 1).join("/");

  const resolved = yield* Effect.try({
    try: () => fileURLToPath(import.meta.resolve(specifier)),
    catch: (cause) => new CliError.UserError({ cause }),
  });

  for (let directory = path.dirname(resolved); ; directory = path.dirname(directory)) {
    const text = yield* fs.readFileString(path.join(directory, "package.json")).pipe(Effect.option);

    if (Option.isSome(text)) {
      const decoded = yield* Schema.decodeEffect(Schema.fromJsonString(PackageJson))(
        text.value,
      ).pipe(Effect.option);

      if (Option.isSome(decoded) && decoded.value.name === name) return decoded.value;
    }

    if (path.dirname(directory) === directory) {
      return yield* new CliError.UserError({ cause: `Cannot find package.json for ${name}.` });
    }
  }
});

const readSource = Effect.fn("readSource")(function* (source: URL) {
  if (source.protocol === "file:") {
    const fs = yield* FileSystem.FileSystem;
    return yield* fs.readFileString(fileURLToPath(source));
  }

  const http = yield* HttpClient.HttpClient;
  const client = HttpClient.filterStatusOk(http);
  const response = yield* client.get(source.href);

  return yield* response.text;
});

const sha256 = Effect.fn("sha256")(function* (text: string) {
  const crypto = yield* Crypto.Crypto;
  const digest = yield* crypto.digest("SHA-256", new TextEncoder().encode(text));
  return [...digest].map((byte) => byte.toString(16).padStart(2, "0")).join("");
});
